package com.pixilife.android;
import android.app.*;import android.database.Cursor;import android.graphics.Color;import android.os.Bundle;import android.widget.*;
public class TasksActivity extends Activity {@Override public void onCreate(Bundle b){super.onCreate(b);LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setPadding(25,25,25,25);r.setBackgroundColor(Color.rgb(7,11,17));TextView h=t("TAREAS Y RECORDATORIOS",25);r.addView(h);MemoryDatabase db=new MemoryDatabase(this);try(Cursor c=db.getReadableDatabase().rawQuery("SELECT text,done FROM tasks ORDER BY created_at DESC",null)){while(c.moveToNext())r.addView(t((c.getInt(1)==1?"HECHA · ":"PENDIENTE · ")+c.getString(0),16));}try(Cursor c=db.getReadableDatabase().rawQuery("SELECT text,due_at,status FROM reminders ORDER BY due_at",null)){while(c.moveToNext())r.addView(t("RECORDATORIO · "+c.getString(0)+"\n"+new java.util.Date(c.getLong(1)),16));}setContentView(r);}private TextView t(String s,int z){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(Color.WHITE);t.setPadding(8,12,8,12);return t;}}
